 "content": "from collections import Counter
from math import gcd
from functools import reduce


def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row)
    common = {v for v, _ in counts.most_common(2)}
    marker_points = [(r, c) for r in range(h) for c in range(w)
                     if grid[r][c] not in common]
    ys = sorted({r for r, _ in marker_points})
    xs = sorted({c for _, c in marker_points})

    def lattice(coords):
        step = reduce(gcd, (b - a for a, b in zip(coords, coords[1:])))
        return list(range(coords[0], coords[-1] + 1, step))

    yr, xc = lattice(ys), lattice(xs)
    out = []
    for r0, r1 in zip(yr, yr[1:]):
        row = []
        for c0, c1 in zip(xc, xc[1:]):
            corners = (grid[r0][c0], grid[r0][c1], grid[r1][c0], grid[r1][c1])
            if corners[0] not in common and all(v == corners[0] for v in corners):
                row.append(corners[0])
            else:
                row.append(grid[(r0 + r1) // 2][(c0 + c1) // 2])
        out.append(row)
    return out
